// Governance tab — renderer (SkyMail, Session 120, 2026-08-05).
//
// STATIC consumer asset (NOT regenerated by excel_to_dashboard.py), lazy-loaded
// by the inline boot in the tab shell on first activation of #tab-governance.
//
// WHY THIS EXISTS. Sam asked what would establish or improve governance, after a
// session where every problem hit turned out to be a governance gap wearing a
// data-quality costume: 25 colleges with no student contact (nobody owned the
// field), a source view with 24 fields of which we read 11 (nobody owned knowing
// the source), test colleges in a public headline (nobody owned the definition
// of "a college"). This tab is the starter artifact — a decision-rights register,
// the acceptance standard per input, and the cadences.
//
// TWO RULES IT FOLLOWS:
//  1. Reasoning is stored (kb/governance_register.json); anything MEASURABLE is
//     computed live at render time. A governance page that states its own
//     compliance from a stored field is a page that can quietly go false.
//  2. It shows what is NOT owned as loudly as what is. Null owners render as a
//     visible gap, because the empty cells are the point of the review.
//
// TEAM-GATED (the sierra_training.js / map_users.js posture): internal working
// material. The live figures come from map_contact_gaps + map_college_nudges,
// which are RLS-gated anyway, so a logged-out visitor would see an empty shell.
(function () {
  "use strict";

  var SUPABASE_URL = "https://hvuwhnbuahrtptokpqfh.supabase.co";
  var SUPABASE_ANON = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imh2dXdobmJ1YWhydHB0b2twcWZoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzU1NzI0ODEsImV4cCI6MjA5MTE0ODQ4MX0.p0q-93iTM0GkF2z8_q7Vvl1tsX9SFGMM-W7Wdx7WfmM";
  var REST = SUPABASE_URL + "/rest/v1";
  var TEAM_PASS_KEY = "cpl_team_pass";
  var REGISTER_URL = "kb/governance_register.json";

  var state = { reg: null, live: null, loading: false, error: null,
                // curated owners keyed by register id (DR-01, CA-03, …); overlays
                // the committed register, which ships every owner null on purpose
                owners: {},
                // true when the owners READ failed — the map below is then the
                // last known-good, not the truth. Never silently render a failed
                // read as "nobody has an owner".
                ownersStale: false,
                // whether the load that populated `owners`/`live` was made while
                // signed in; a change means those gated reads must be redone
                loadedSignedIn: false };

  // ── Auth (shared cpl_sb magic-link session + cpl_team_pass phrase) ──
  function isValidJwt(t) { return typeof t === "string" && t.split(".").length === 3 && t.length > 40; }
  function getSession() {
    try {
      var s = JSON.parse(sessionStorage.getItem("cpl_sb") || "null");
      if (s && isValidJwt(s.access_token)) return { access_token: s.access_token, email: s.email || "(reviewer)" };
    } catch (e) {}
    try {
      var p = localStorage.getItem(TEAM_PASS_KEY);
      if (p) return { teamPass: p, email: "(team)" };
    } catch (e) {}
    return null;
  }
  function authHeaders() {
    var s = getSession();
    var token = (s && s.access_token) || SUPABASE_ANON;
    var h = { apikey: SUPABASE_ANON, Authorization: "Bearer " + token };
    if (s && s.teamPass) h["x-team-pass"] = s.teamPass;
    return h;
  }
  function signedIn() { return !!getSession(); }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  var CSS_ID = "governance-css";
  function ensureCss() {
    if (document.getElementById(CSS_ID)) return;
    var css = [
      ".gov { max-width: 1100px; margin: 0 auto; color: var(--text-body); }",
      ".gov h2 { color: var(--navy-primary); margin: 16px 0 4px; }",
      ".gov h3 { color: var(--navy-primary); margin: 26px 0 4px; font-size: 1.05rem; }",
      ".gov-intro { color: var(--text-muted); max-width: 900px; margin: 0 0 14px; font-size: .92rem; }",
      ".gov-draft { font-size:.66rem; text-transform:uppercase; letter-spacing:.05em; background: var(--surface-muted);"
        + " color: var(--text-muted); border-radius:10px; padding:2px 9px; vertical-align:middle; }",
      ".gov-principle { border-left:3px solid var(--seal-blue); padding:8px 12px; margin:0 0 16px;"
        + " background: var(--surface-subtle); font-size:.92rem; }",
      ".gov-stat { display:flex; flex-wrap:wrap; gap:10px; margin:0 0 18px; }",
      ".gov-stat .box { flex:1 1 160px; border:1px solid var(--border); border-radius:8px;"
        + " background: var(--surface-subtle); padding:10px 12px; }",
      ".gov-stat .box .n { font-size:1.4rem; font-weight:700; color: var(--navy-primary); }",
      ".gov-stat .box .l { font-size:.72rem; color: var(--text-muted); }",
      ".gov-table { width:100%; border-collapse:collapse; table-layout:fixed; font-size:.82rem; margin:0 0 6px; }",
      ".gov-table th { text-align:left; padding:6px 8px; border-bottom:2px solid var(--border-strong);"
        + " color: var(--text-muted); font-size:.72rem; text-transform:uppercase; letter-spacing:.03em; }",
      ".gov-table td { padding:7px 8px; border-bottom:1px solid var(--border); vertical-align:top; }",
      ".gov-id { font-size:.68rem; color: var(--text-muted); font-variant-numeric:tabular-nums; }",
      ".gov-el { font-weight:600; }",
      ".gov-noown { color: var(--danger, #b3261e); font-weight:600; }",
      ".gov-chip { font-size:.68rem; border-radius:10px; padding:1px 8px; white-space:nowrap;"
        + " background: var(--surface-muted); color: var(--text-muted); }",
      ".gov-chip.auth { background: var(--hunter, #2c601a); color:#fff; }",
      ".gov-chip.corrob { background: var(--surface-muted); color: var(--text-body); }",
      ".gov-chip.advis { background: var(--surface-subtle); color: var(--text-muted); }",
      ".gov-live { font-size:.72rem; color: var(--text-muted); }",
      ".gov-live b { color: var(--navy-primary); }",
      ".gov-bad { color: var(--danger, #b3261e); font-weight:600; }",
      ".gov-note { font-size:.75rem; color: var(--text-muted); margin-top:4px; }",
      ".gov-gate { color: var(--text-muted); padding:18px; border:1px dashed var(--border-strong);"
        + " border-radius:8px; background: var(--surface-subtle); }",
      ".gov-btn { font-size:.78rem; padding:4px 10px; border:1px solid var(--border); border-radius:6px;"
        + " background: var(--surface); color: var(--text-body); cursor:pointer; }",
      ".gov-btn:hover { border-color: var(--seal-blue); color: var(--seal-blue); }",
      ".gov-toolbar { display:flex; gap:8px; align-items:center; margin:0 0 14px; flex-wrap:wrap; }",
      ".gov-q { border-left:3px solid var(--border-strong); padding:6px 12px; margin:0 0 10px; }",
      ".gov-q .qq { font-weight:600; }",
      ".gov-q .qw { font-size:.8rem; color: var(--text-muted); }",
      // Owner curation
      ".gov-ownbtn { display:block; width:100%; text-align:left; background:none; border:1px dashed transparent;"
        + " border-radius:6px; padding:3px 5px; cursor:pointer; font:inherit; color:inherit; }",
      ".gov-ownbtn:hover { border-color: var(--seal-blue); background: var(--surface-subtle); }",
      ".gov-owner { font-weight:600; color: var(--navy-primary); }",
      ".gov-pencil { opacity:0; float:right; font-size:.8rem; color: var(--seal-blue); }",
      ".gov-ownbtn:hover .gov-pencil { opacity:1; }",
      ".gov-ov { position:fixed; inset:0; background:rgba(0,0,0,.42); z-index:400;"
        + " display:flex; align-items:center; justify-content:center; padding:20px; }",
      ".gov-dlg { background: var(--surface); border-radius:10px; padding:18px 20px; max-width:460px;"
        + " width:100%; box-shadow:0 8px 30px rgba(0,0,0,.3); }",
      ".gov-dlg h3 { margin:0 0 6px; font-size:1rem; color: var(--navy-primary); }",
      ".gov-dlg label { display:block; font-size:.75rem; color: var(--text-muted); margin:10px 0 3px; }",
      ".gov-dlg input, .gov-dlg textarea { width:100%; padding:7px 9px; border:1px solid var(--border);"
        + " border-radius:6px; font:inherit; font-size:.85rem; background: var(--surface); color: var(--text-body); }",
      ".gov-dlg textarea { min-height:56px; resize:vertical; }",
      ".gov-dlg-actions { display:flex; gap:8px; justify-content:flex-end; margin-top:14px; }",
      ".gov-dlg-what { font-size:.78rem; color: var(--text-muted); margin:0 0 4px; }",
      "@media (max-width: 820px) { .gov-table { display:block; overflow-x:auto; } }",
    ].join("\n");
    var el = document.createElement("style");
    el.id = CSS_ID; el.textContent = css;
    document.head.appendChild(el);
  }

  // ── Live measurements ─────────────────────────────────────────────────────
  // Everything a governance page could LIE about is measured here instead of
  // being stored. If the register says a cadence runs and it hasn't, the tab
  // says so — that honesty is the whole value of the page.
  function loadLive() {
    var out = {};
    var gaps = fetch(REST + "/map_contact_gaps?select=college,college_kind,has_student_contact,"
        + "has_coordinator,landing_page_url,active_users,synced_at", { headers: authHeaders() })
      .then(function (r) { return r.ok ? r.json() : []; })
      .then(function (rows) {
        var real = (rows || []).filter(function (r) { return r.college_kind === "college"; });
        out.total = real.length;
        out.pc = real.filter(function (r) { return r.has_student_contact; }).length;
        out.coord = real.filter(function (r) { return r.has_coordinator; }).length;
        out.landing = real.filter(function (r) { return !!r.landing_page_url; }).length;
        out.zeroUsers = real.filter(function (r) { return !r.active_users; }).length;
        out.synced = real.reduce(function (m, r) {
          return (!m || (r.synced_at && r.synced_at > m)) ? r.synced_at : m; }, null);
      }).catch(function () {});
    var nudges = fetch(REST + "/map_college_nudges?select=college,last_nudged_at", { headers: authHeaders() })
      .then(function (r) { return r.ok ? r.json() : []; })
      .then(function (rows) {
        out.nudgeCount = (rows || []).length;
        out.lastNudge = (rows || []).reduce(function (m, r) {
          return (!m || (r.last_nudged_at && r.last_nudged_at > m)) ? r.last_nudged_at : m; }, null);
      }).catch(function () { out.nudgeCount = 0; });
    // CA-06 — Sierra feedback triage. Counts only REAL rows: page='smoke' is the CI
    // smoke test writing through the public anon RPC on every run, and it cannot
    // delete its own rows (anon is deliberately write-only on that table). On
    // 2026-08-07 it was 28 of 53, so an unfiltered "untriaged" figure here would be
    // majority robot — a governance page reporting its own CI back to itself.
    var fb = fetch(REST + "/sierra_feedback?select=page,status&limit=1000", { headers: authHeaders() })
      .then(function (r) { return r.ok ? r.json() : []; })
      .then(function (rows) {
        var real = (rows || []).filter(function (r) { return r.page !== "smoke"; });
        out.fbTotal = real.length;
        out.fbOpen = real.filter(function (r) { return (r.status || "new") !== "addressed"; }).length;
      }).catch(function () {});
    return Promise.all([gaps, nudges, fb]).then(function () { return out; });
  }

  function fmtDate(s) {
    if (!s) return "—";
    var d = new Date(s);
    return isNaN(d.getTime()) ? esc(String(s).slice(0, 10)) : d.toISOString().slice(0, 10);
  }

  // ── Owner curation ────────────────────────────────────────────────────────
  // The register is COMMITTED and rebuilt by sessions; owners are set LIVE by the
  // team. Different lifecycles, different homes — governance_owners overlays the
  // JSON by row id, so a session regenerating the register can never wipe an
  // assignment. Same split that keeps the nudge log out of the contacts table.
  function loadOwners() {
    // A FAILED READ IS NOT "NOBODY HAS AN OWNER". This used to be
    // `r.ok ? r.json() : []`, which turned a 401, a 500 or an RLS change into an
    // empty owner map — every colleague's assignment vanished from the page and
    // the red "Rows with no owner" stat jumped to its maximum, with nothing on
    // screen saying a read had failed. On a page whose entire purpose is showing
    // who is accountable, silently reporting "no one" because the network hiccuped
    // is the worst available answer. Keep the last known-good map and flag it.
    return fetch(REST + "/governance_owners?select=register_id,owner,note,set_by,set_at",
      { headers: authHeaders() })
      .then(function (r) {
        if (!r.ok) throw new Error("owners " + r.status);
        return r.json();
      })
      .then(function (rows) {
        var by = {};
        (rows || []).forEach(function (o) { by[o.register_id] = o; });
        state.owners = by;
        state.ownersStale = false;
        return by;
      }).catch(function () {
        state.ownersStale = true;   // render surfaces this; owners are NOT wiped
        return null;
      });
  }
  // Resolved owner for a row: a curated value wins over the file's.
  function ownerOf(row) {
    if (!row || !row.id) return null;
    var c = state.owners[row.id];
    if (c && typeof c.owner === "string" && c.owner.trim()) {
      return { name: c.owner.trim(), by: c.set_by, at: c.set_at, note: c.note, curated: true };
    }
    if (row.owner) return { name: row.owner, curated: false };
    return null;
  }
  function saveOwner(id, name, note) {
    var sess = getSession();
    var payload = { register_id: id, owner: name || null, note: note || null,
                    set_by: (sess && sess.email) || "(team)", set_at: new Date().toISOString() };
    state.owners[id] = payload;   // optimistic — the row repaints immediately
    var h = authHeaders();
    h["Content-Type"] = "application/json";
    h["Prefer"] = "resolution=merge-duplicates,return=minimal";
    return fetch(REST + "/governance_owners", {
      method: "POST", headers: h, body: JSON.stringify([payload]),
    }).then(function (r) {
      if (!r.ok) throw new Error("save " + r.status);
      return true;
    });
  }

  // Renders the live figure a register row points at via its `live` key. Returns
  // "" when a row has nothing measurable — most don't, and that's fine.
  function liveCell(key) {
    var L = state.live || {};
    if (!key || !L.total) return "";
    if (key === "contact_pc") {
      var missing = L.total - L.pc;
      return '<div class="gov-live"><b>' + L.pc + "</b> of " + L.total + " on file"
        + (missing ? ' · <span class="gov-bad">' + missing + " route nowhere</span>" : "") + "</div>";
    }
    if (key === "contact_coord") return '<div class="gov-live"><b>' + L.coord + "</b> of " + L.total + " on file</div>";
    if (key === "landing") {
      var noPage = L.total - L.landing;
      return '<div class="gov-live"><b>' + L.landing + "</b> of " + L.total + " have a page"
        + (noPage ? ' · <span class="gov-bad">' + noPage + " without</span>" : "") + "</div>";
    }
    if (key === "users") {
      return '<div class="gov-live">' + (L.zeroUsers
        ? '<span class="gov-bad">' + L.zeroUsers + "</span> institutions with zero active users"
        : "every institution has active users") + "</div>";
    }
    return "";
  }

  function cadenceState(c) {
    var L = state.live || {};
    if (c.live === "nudge") {
      return L.nudgeCount
        ? '<span class="gov-live">last run <b>' + fmtDate(L.lastNudge) + "</b> · " + L.nudgeCount + " colleges</span>"
        : '<span class="gov-bad">never run</span>';
    }
    if (c.live === "sync") return '<span class="gov-live">last sync <b>' + fmtDate(L.synced) + "</b></span>";
    if (c.live === "feedback") {
      if (L.fbTotal == null) return '<span class="gov-live">' + esc(c.state || "—") + "</span>";
      return L.fbOpen
        ? '<span class="gov-bad">' + L.fbOpen + " of " + L.fbTotal + " untriaged</span>"
        : '<span class="gov-live">all <b>' + L.fbTotal + "</b> triaged</span>";
    }
    return '<span class="gov-live">' + esc(c.state || "—") + "</span>";
  }

  function stanceChip(stance) {
    var cls = /^authoritative/.test(stance) ? "auth" : (/corrobor/.test(stance) ? "corrob" : "advis");
    return '<span class="gov-chip ' + cls + '">' + esc(stance) + "</span>";
  }
  // Owner cell — click to assign. An unowned row stays visibly red rather than
  // showing a tidy blank, because the gaps are the point of the page.
  function owner(row) {
    var o = ownerOf(row);
    var body = o
      ? '<span class="gov-owner">' + esc(o.name) + "</span>"
        + (o.curated ? '<div class="gov-note">set by ' + esc(o.by || "?") + " · " + fmtDate(o.at) + "</div>" : "")
        + (o.note ? '<div class="gov-note">' + esc(o.note) + "</div>" : "")
      : '<span class="gov-noown">needs an owner</span>';
    return '<button class="gov-ownbtn" data-own="' + esc(row.id)
      + '" title="Click to assign an owner">' + body + '<span class="gov-pencil">✎</span></button>';
  }

  function render(root) {
    ensureCss();
    if (!signedIn()) {
      root.innerHTML = '<div class="gov"><h2>Governance</h2>'
        + '<div class="gov-gate">This is internal working material — sign in on the '
        + "<b>Team &amp; RACI</b> tab (reviewer sign-in or the shared team phrase) to view it.</div></div>";
      return;
    }
    if (state.loading) { root.innerHTML = '<div class="gov"><p class="gov-gate">Loading the governance register…</p></div>'; return; }
    if (state.error || !state.reg) {
      root.innerHTML = '<div class="gov"><div class="gov-gate">Could not load the register ('
        + esc(state.error || "no data") + ").</div></div>";
      return;
    }
    var R = state.reg, L = state.live || {};
    var unowned = (R.decision_rights || []).concat(R.cadences || [])
      .filter(function (r) { return !ownerOf(r); }).length;

    var h = '<div class="gov"><h2>Governance <span class="gov-draft">Draft · for review</span></h2>';
    // A failed owners read must announce itself. Without this the page renders a
    // confident "N rows have no owner" computed from data it could not fetch.
    if (state.ownersStale) {
      h += '<div class="gov-gate"><b>Could not read the assigned owners.</b> The owner column below may be '
        + "out of date, and the “no owner” count cannot be trusted until this loads. Re-open the tab, or "
        + "renew your session on the <b>Team &amp; RACI</b> tab.</div>";
    }
    h += '<p class="gov-intro">A starter register: <b>who decides what</b>, <b>how much we trust each input</b>, '
      + "and <b>which loops actually run</b>. Written after a session in which every problem turned out to be a "
      + "governance gap wearing a data-quality costume — a field nobody owned, a source nobody owned knowing, "
      + "a definition nobody owned. Reasoning is stored; anything measurable is computed live on this page, so "
      + "it cannot quietly disagree with reality. <b>Click any owner cell to assign one.</b></p>";
    h += '<div class="gov-principle">' + esc(R._principle || "") + "</div>";

    h += '<div class="gov-stat">'
      + '<div class="box"><div class="n">' + (R.decision_rights || []).length + '</div><div class="l">Decision rights</div></div>'
      + '<div class="box"><div class="n gov-noown">' + unowned + '</div><div class="l">Rows with no owner</div></div>'
      + '<div class="box"><div class="n">' + (L.total || "—") + '</div><div class="l">Colleges in scope</div></div>'
      + '<div class="box"><div class="n' + (L.total && L.pc < L.total ? " gov-noown" : "") + '">'
      + (L.total ? (L.total - L.pc) : "—") + '</div><div class="l">Route a student nowhere</div></div>'
      + "</div>";

    h += '<div class="gov-toolbar"><button class="gov-btn" data-gov-copy>⧉ Copy as Markdown</button>'
      + '<span class="gov-live">Share it with anyone who should be in this conversation.</span></div>';

    // ── Decision rights ──
    h += "<h3>Who decides what</h3>";
    h += '<p class="gov-intro">The load-bearing question for each element: <b>whose call is this?</b> '
      + "Where the answer is “the college,” our job is to route to a determination they already made — never to "
      + "make one for them. Where it is ours, say so plainly; ambiguity produces both over-reach and paralysis.</p>";
    h += '<table class="gov-table"><colgroup><col style="width:20%"><col style="width:26%"><col style="width:14%">'
      + '<col style="width:14%"><col style="width:26%"></colgroup><thead><tr>'
      + "<th>Element</th><th>What it drives</th><th>Who decides</th><th>Our owner</th><th>When it's empty</th>"
      + "</tr></thead><tbody>";
    (R.decision_rights || []).forEach(function (d) {
      h += "<tr>"
        + '<td><span class="gov-id">' + esc(d.id) + '</span><br><span class="gov-el">' + esc(d.element) + "</span>"
        + (d.load_bearing ? ' <span class="gov-chip">load-bearing</span>' : "") + "</td>"
        + "<td>" + esc(d.drives) + liveCell(d.live) + "</td>"
        + "<td>" + esc(d.decides) + '<div class="gov-note">' + esc(d.maintained_in || "") + "</div></td>"
        + "<td>" + owner(d) + "</td>"
        + "<td>" + esc(d.when_empty) + "</td></tr>";
    });
    h += "</tbody></table>";

    // ── Acceptance standards ──
    h += "<h3>How far each input is trusted</h3>";
    h += '<p class="gov-intro">You already have the best version of this for TOP codes — '
      + "<b>corroborating only, never gating, two-signals-agree</b>. That standard is the template; the rest of "
      + "this table applies it to every other input. Decide a new input's stance <i>before</i> depending on it.</p>";
    h += '<table class="gov-table"><colgroup><col style="width:20%"><col style="width:18%"><col style="width:62%">'
      + "</colgroup><thead><tr><th>Input</th><th>Stance</th><th>Rule</th></tr></thead><tbody>";
    (R.acceptance_standards || []).forEach(function (a) {
      h += "<tr><td><span class=\"gov-id\">" + esc(a.id) + '</span><br><span class="gov-el">'
        + esc(a.input) + "</span></td><td>" + stanceChip(a.stance) + "</td><td>" + esc(a.rule) + "</td></tr>";
    });
    h += "</tbody></table>";

    // ── Cadences ──
    h += "<h3>Which loops actually run</h3>";
    h += '<p class="gov-intro">A cadence nobody runs is a document, not governance. The "last run" column is '
      + "measured live, not asserted — which is the point.</p>";
    h += '<table class="gov-table"><colgroup><col style="width:26%"><col style="width:22%"><col style="width:18%">'
      + '<col style="width:34%"></colgroup><thead><tr>'
      + "<th>Loop</th><th>Frequency</th><th>Owner</th><th>State</th></tr></thead><tbody>";
    (R.cadences || []).forEach(function (c) {
      h += "<tr><td><span class=\"gov-id\">" + esc(c.id) + '</span><br><span class="gov-el">'
        + esc(c.loop) + "</span></td><td>" + esc(c.frequency) + "</td><td>" + owner(c) + "</td>"
        + "<td>" + cadenceState(c) + (c.note ? '<div class="gov-note">' + esc(c.note) + "</div>" : "")
        + "</td></tr>";
    });
    h += "</tbody></table>";

    // ── Open questions ──
    h += "<h3>Open questions — the actual review</h3>";
    (R.open_questions || []).forEach(function (q) {
      h += '<div class="gov-q"><div class="qq"><span class="gov-id">' + esc(q.id) + "</span> " + esc(q.q)
        + '</div><div class="qw">' + esc(q.why) + "</div></div>";
    });

    h += '<p class="gov-note">Register: <code>kb/governance_register.json</code> · '
      + "live figures from the gated MAP contact tables · draft by SkyMail (Session 120), "
      + esc(R._as_of || "") + "</p></div>";
    root.innerHTML = h;
    wire(root);
  }

  // Markdown export so this can leave the tab and enter an actual meeting.
  function toMarkdown() {
    var R = state.reg || {}, L = state.live || {};
    var out = ["# CPL Initiative — governance register (DRAFT)", "", R._principle || "", ""];
    if (L.total) {
      out.push("**Live:** " + L.pc + " of " + L.total + " colleges have a student-facing CPL contact; "
        + (L.total - L.pc) + " route a student's request nowhere.", "");
    }
    out.push("## Who decides what", "", "| Element | Drives | Who decides | Our owner | When empty |", "|---|---|---|---|---|");
    (R.decision_rights || []).forEach(function (d) {
      out.push("| " + d.element + " | " + d.drives + " | " + d.decides + " | "
        + ((ownerOf(d) || {}).name || "**needs an owner**") + " | " + d.when_empty + " |");
    });
    out.push("", "## How far each input is trusted", "", "| Input | Stance | Rule |", "|---|---|---|");
    (R.acceptance_standards || []).forEach(function (a) {
      out.push("| " + a.input + " | " + a.stance + " | " + a.rule + " |");
    });
    out.push("", "## Which loops actually run", "", "| Loop | Frequency | Owner | State |", "|---|---|---|---|");
    (R.cadences || []).forEach(function (c) {
      var st = c.live === "nudge" ? (L.nudgeCount ? "last run " + fmtDate(L.lastNudge) : "**NEVER RUN**")
        : (c.live === "sync" ? "last sync " + fmtDate(L.synced)
        : (c.live === "feedback" && L.fbTotal != null
            ? (L.fbOpen ? "**" + L.fbOpen + " of " + L.fbTotal + " UNTRIAGED**" : "all " + L.fbTotal + " triaged")
            : (c.state || "")));
      out.push("| " + c.loop + " | " + c.frequency + " | " + ((ownerOf(c) || {}).name || "**needs an owner**") + " | " + st + " |");
    });
    out.push("", "## Open questions", "");
    (R.open_questions || []).forEach(function (q) { out.push("- **" + q.q + "** — " + q.why); });
    return out.join("\n");
  }

  // The assign-owner dialog. Deliberately plain — a name and an optional note.
  // "Who is accountable" is a human answer; asking for more structure than that
  // is how a review turns into a form nobody fills in.
  function openOwnerDialog(root, id) {
    var R = state.reg || {};
    var row = (R.decision_rights || []).concat(R.cadences || [])
      .filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var cur = ownerOf(row);
    var old = document.getElementById("gov-own-dlg");
    if (old) old.parentNode.removeChild(old);
    var ov = document.createElement("div");
    ov.id = "gov-own-dlg"; ov.className = "gov-ov";
    ov.innerHTML = '<div class="gov-dlg" role="dialog" aria-label="Assign an owner">'
      + "<h3>" + esc(row.element || row.loop) + "</h3>"
      + '<p class="gov-dlg-what"><span class="gov-id">' + esc(id) + "</span> — "
      + esc(row.drives || row.frequency || "") + "</p>"
      + '<label for="gov-own-name">Owner — who is accountable for this?</label>'
      + '<input id="gov-own-name" type="text" placeholder="e.g. Jessica, or Ashley + Malone" value="'
      + esc(cur ? cur.name : "") + '">'
      + '<label for="gov-own-note">Note (optional)</label>'
      + '<textarea id="gov-own-note" placeholder="Scope, caveats, or what exactly they own">'
      + esc(cur && cur.note ? cur.note : "") + "</textarea>"
      + '<div class="gov-dlg-actions">'
      + '<button class="gov-btn" data-own-cancel>Cancel</button>'
      + '<button class="gov-btn" data-own-clear>Clear owner</button>'
      + '<button class="gov-btn" data-own-save><b>Save</b></button>'
      + "</div></div>";
    document.body.appendChild(ov);
    function close() { if (ov.parentNode) ov.parentNode.removeChild(ov); }
    ov.addEventListener("click", function (e) { if (e.target === ov) close(); });
    ov.querySelector("[data-own-cancel]").addEventListener("click", close);
    var nameEl = ov.querySelector("#gov-own-name");
    if (nameEl.focus) nameEl.focus();
    function commit(name) {
      var note = ov.querySelector("#gov-own-note").value.trim();
      close();
      // ORDER IS LOAD-BEARING. saveOwner() performs the optimistic local write
      // (state.owners[id] = payload) synchronously, before its fetch — so the
      // repaint must come AFTER it. It used to come before, which meant the
      // first Save painted the pre-change state and the row still read "needs an
      // owner"; the value only appeared when the dialog was reopened and saved a
      // SECOND time, because by then the first click's write was in state. The
      // save itself had always worked — only the UI lied. (Sam, 2026-08-07.)
      var saving = saveOwner(id, name, note);
      render(root);
      saving.catch(function () {
        alert("Could not save that owner. Sign in on the Team & RACI tab "
          + "(reviewer or team phrase) and try again.");
        loadOwners().then(function () { render(root); });
      });
    }
    ov.querySelector("[data-own-save]").addEventListener("click", function () { commit(nameEl.value.trim()); });
    ov.querySelector("[data-own-clear]").addEventListener("click", function () { commit(""); });
    nameEl.addEventListener("keydown", function (e) { if (e.key === "Enter") commit(nameEl.value.trim()); });
  }

  function wire(root) {
    root.querySelectorAll("[data-own]").forEach(function (b) {
      b.addEventListener("click", function () { openOwnerDialog(root, b.getAttribute("data-own")); });
    });
    var btn = root.querySelector("[data-gov-copy]");
    if (!btn) return;
    btn.addEventListener("click", function () {
      var md = toMarkdown();
      var done = function () { btn.textContent = "✓ Copied"; setTimeout(function () { btn.textContent = "⧉ Copy as Markdown"; }, 1400); };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(md).then(done, done);
      } else {
        var ta = document.createElement("textarea");
        ta.value = md; document.body.appendChild(ta); ta.select();
        try { document.execCommand("copy"); } catch (e) {}
        ta.remove(); done();
      }
    });
  }

  function activate() {
    var root = document.getElementById("governance-root");
    if (!root) return;
    // Re-fetch when the SIGN-IN STATE has changed since we loaded, not just when
    // we have never loaded. The gated reads (live figures, curated owners) are
    // skipped while logged out, so a tab first opened logged-out kept its empty
    // results forever: sign in, come back, and you get a fully-populated-looking
    // register with every owner missing and a cadence accused in red of having
    // never run — all of it an artifact of the reads that were never made.
    if (state.reg && state.loadedSignedIn === signedIn()) { render(root); return; }
    state.loading = true; render(root);
    Promise.all([
      fetch(REGISTER_URL).then(function (r) {
        if (!r.ok) throw new Error("register " + r.status);
        return r.json();
      }),
      signedIn() ? loadLive() : Promise.resolve({}),
      signedIn() ? loadOwners() : Promise.resolve({}),
    ]).then(function (res) {
      state.reg = res[0]; state.live = res[1] || {};
      state.loadedSignedIn = signedIn();   // what this load was ALLOWED to read
      state.loading = false; render(root);
    }).catch(function (e) {
      state.loading = false; state.error = (e && e.message) || "error"; render(root);
    });
  }

  window.CPL_GOVERNANCE = {
    activate: activate,
    render: render,
    _state: state,
    _toMarkdown: toMarkdown,
    _liveCell: liveCell,
    _cadenceState: cadenceState,
    _owner: owner,
    _ownerOf: ownerOf,
    _stanceChip: stanceChip,
    _loadOwners: loadOwners,   // exported so the failed-read path is testable
    _signedIn: signedIn,
  };

  // tabs.js dispatches cpl-tab-activated on WINDOW, not document.
  window.addEventListener("cpl-tab-activated", function (e) {
    if (e && e.detail && e.detail.tab === "governance") activate();
  });
})();
